import Foundation

let filePath = "<tmp>"

let content = try! String(contentsOfFile: filePath, encoding: .utf8)
var lines = content.components(separatedBy: "\n").map { $0.hasSuffix("\r") ? String($0.dropLast()) : $0 }.filter { !$0.isEmpty }

func formatWithCommas(_ value: Double, decimals: Int) -> String {
    let formatted: String
    if decimals == 0 {
        formatted = String(format: "%.0f", value)
    } else {
        formatted = String(format: "%.\(decimals)f", value)
    }
    let parts = formatted.components(separatedBy: ".")
    let intPart = parts[0]
    let fracPart = parts.count > 1 ? parts[1] : ""

    var negative = false
    var digits = intPart
    if digits.hasPrefix("-") {
        negative = true
        digits = String(digits.dropFirst())
    }

    var result = ""
    var count = 0
    for char in digits.reversed() {
        if count > 0 && count % 3 == 0 {
            result = "," + result
        }
        result = String(char) + result
        count += 1
    }
    if negative { result = "-" + result }
    if decimals > 0 {
        return "$" + result + "." + fracPart
    }
    return "$" + result
}

var departments: [String: [Double]] = [:]
var employees: [(name: String, salary: Double)] = []

for i in 1..<lines.count {
    let fields = lines[i].components(separatedBy: ",")
    let name = fields[1]
    let dept = fields[2]
    let salary = Double(fields[3])!
    departments[dept, default: []].append(salary)
    employees.append((name: name, salary: salary))
}

print("=== Salary Report ===")
print()
print("Average Salary by Department:")
let sortedDepts = departments.keys.sorted()
for dept in sortedDepts {
    let salaries = departments[dept]!
    let avg = salaries.reduce(0, +) / Double(salaries.count)
    print("  \(dept): \(formatWithCommas(avg, decimals: 2))")
}
print()

let highest = employees.max(by: { $0.salary < $1.salary })!
print("Highest Paid: \(highest.name) (\(formatWithCommas(highest.salary, decimals: 0)))")
print()

print("Departments with >2 employees:")
for dept in sortedDepts {
    let count = departments[dept]!.count
    if count > 2 {
        print("  \(dept) (\(count) employees)")
    }
}
print()

let totalBudget = employees.reduce(0.0) { $0 + $1.salary }
print("Total Budget: \(formatWithCommas(totalBudget, decimals: 0))")

