declare function require(module: string): any;

const fs = require('fs');

const pathA = '<tmp>';
const pathB = '<tmp>';

function isPlainObject(val: any): boolean {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

function mergeArrays(a: any[], b: any[]): any[] {
  const result: any[] = [...a];
  for (const item of b) {
    const jsonItem = JSON.stringify(item);
    const exists = result.some((existing: any) => JSON.stringify(existing) === jsonItem);
    if (!exists) {
      result.push(item);
    }
  }
  return result;
}

function deepMerge(a: any, b: any): any {
  if (isPlainObject(a) && isPlainObject(b)) {
    const result: { [key: string]: any } = {};
    const keys = new Set<string>([...Object.keys(a), ...Object.keys(b)]);
    for (const key of keys) {
      if (key in a && key in b) {
        result[key] = deepMerge(a[key], b[key]);
      } else if (key in a) {
        result[key] = a[key];
      } else {
        result[key] = b[key];
      }
    }
    return result;
  }
  if (Array.isArray(a) && Array.isArray(b)) {
    return mergeArrays(a, b);
  }
  return b;
}

function sortKeys(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(sortKeys);
  }
  if (isPlainObject(obj)) {
    const sorted: { [key: string]: any } = {};
    const keys = Object.keys(obj).sort();
    for (const key of keys) {
      sorted[key] = sortKeys(obj[key]);
    }
    return sorted;
  }
  return obj;
}

const a = JSON.parse(fs.readFileSync(pathA, 'utf-8'));
const b = JSON.parse(fs.readFileSync(pathB, 'utf-8'));

const merged = deepMerge(a, b);
const sorted = sortKeys(merged);
process.stdout.write(JSON.stringify(sorted, null, 2) + '\n');

