import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (!line.trim().isEmpty()) {
                    lines.add(line);
                }
            }
        }

        Pattern pattern = Pattern.compile("^\\[(\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)$");

        Map<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> errorComponentCounts = new HashMap<>();
        Set<String> errorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        for (String line : lines) {
            Matcher m = pattern.matcher(line);
            if (m.matches()) {
                String timestamp = m.group(1);
                String level = m.group(2);
                String component = m.group(3);
                String message = m.group(4);

                levelCounts.merge(level, 1, Integer::sum);

                if (level.equals("ERROR")) {
                    errorComponentCounts.merge(component, 1, Integer::sum);
                    errorMessages.add(message);
                }

                String hour = timestamp.substring(11, 13);
                hourCounts.merge(hour, 1, Integer::sum);
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== Log Analysis ===\n");
        sb.append("\n");
        sb.append("Entries by Level:\n");
        for (Map.Entry<String, Integer> e : levelCounts.entrySet()) {
            sb.append("  ").append(e.getKey()).append(": ").append(e.getValue()).append("\n");
        }
        sb.append("\n");

        String topComponent = "";
        int topCount = 0;
        for (Map.Entry<String, Integer> e : errorComponentCounts.entrySet()) {
            if (e.getValue() > topCount || (e.getValue() == topCount && e.getKey().compareTo(topComponent) < 0)) {
                topCount = e.getValue();
                topComponent = e.getKey();
            }
        }
        sb.append("Component with Most Errors: ").append(topComponent).append(" (").append(topCount).append(" errors)\n");
        sb.append("\n");

        sb.append("Unique Error Messages:\n");
        for (String msg : errorMessages) {
            sb.append("  - ").append(msg).append("\n");
        }
        sb.append("\n");

        String busiestHour = "";
        int busiestCount = 0;
        for (Map.Entry<String, Integer> e : hourCounts.entrySet()) {
            if (e.getValue() > busiestCount || (e.getValue() == busiestCount && e.getKey().compareTo(busiestHour) < 0)) {
                busiestCount = e.getValue();
                busiestHour = e.getKey();
            }
        }
        sb.append("Busiest Hour: ").append(busiestHour).append(":00 (").append(busiestCount).append(" entries)\n");

        System.out.print(sb.toString());
    }
}

