    guard let spaceIdx = afterBracket.firstIndex(of: " ") else { continue }
    let level = String(afterBracket[afterBracket.startIndex..<spaceIdx])

    let afterLevel = afterBracket[afterBracket.index(after: spaceIdx)...].trimmingCharacters(in: .whitespaces)

