use std::fs;
use std::collections::BTreeMap;

fn format_commas(n: u64) -> String {
    let s = n.to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        result.push(c);
        let remaining = len - i - 1;
        if remaining > 0 && remaining % 3 == 0 {
            result.push(',');
        }
    }
    result
}

fn main() {
    let content = fs::read_to_string("<tmp>")
        .expect("Failed to read file");
    let content = content.trim_start_matches('\u{feff}');

    let lines: Vec<&str> = content.lines().collect();

    let mut depts: BTreeMap<String, (f64, u64)> = BTreeMap::new();
    let mut highest_name = String::new();
    let mut highest_salary: f64 = 0.0;
    let mut total_budget: f64 = 0.0;

    for line in &lines[1..] {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim();
        let department = fields[2].trim();
        let salary: f64 = fields[3].trim().parse().unwrap();

        let entry = depts.entry(department.to_string()).or_insert((0.0, 0));
        entry.0 += salary;
        entry.1 += 1;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name.to_string();
        }

        total_budget += salary;
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, (sum, count)) in &depts {
        let avg_cents = (sum * 100.0 / *count as f64).round() as i64;
        let int_part = (avg_cents / 100) as u64;
        let dec_part = (avg_cents % 100) as u64;
        let int_str = format_commas(int_part);
        println!("  {}: ${}.{:02}", dept, int_str, dec_part);
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_commas(highest_salary as u64));
    println!();
    println!("Departments with >2 employees:");
    for (dept, (_, count)) in &depts {
        if *count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_commas(total_budget as u64));
}

