    visited.add(u)
    for v, w in adj[u]:
        if v not in visited:
            new_dist = d + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))

print("=== Shortest Paths from A ===")
