import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";
        String json = new String(java.nio.file.Files.readAllBytes(java.nio.file.Paths.get(path)));

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        int nodesKeyIdx = json.indexOf("\"nodes\"");
        int nodesBracketStart = json.indexOf('[', nodesKeyIdx);
        int nodesBracketEnd = findMatchingBracket(json, nodesBracketStart);
        String nodesStr = json.substring(nodesBracketStart + 1, nodesBracketEnd);
        // Extract quoted strings
        int i = 0;
        while (i < nodesStr.length()) {
            int q1 = nodesStr.indexOf('"', i);
            if (q1 == -1) break;
            int q2 = nodesStr.indexOf('"', q1 + 1);
            if (q2 == -1) break;
            nodes.add(nodesStr.substring(q1 + 1, q2));
            i = q2 + 1;
        }

        // Parse edges
        Map<String, List<String[]>> adj = new HashMap<>();
        for (String n : nodes) {
            adj.put(n, new ArrayList<>());
        }

        int edgesKeyIdx = json.indexOf("\"edges\"");
        int edgesBracketStart = json.indexOf('[', edgesKeyIdx);
        int edgesBracketEnd = findMatchingBracket(json, edgesBracketStart);
        String edgesStr = json.substring(edgesBracketStart + 1, edgesBracketEnd);

        // Parse each edge object
        int pos = 0;
        while (pos < edgesStr.length()) {
            int objStart = edgesStr.indexOf('{', pos);
            if (objStart == -1) break;
            int objEnd = findMatchingBrace(edgesStr, objStart);
            String obj = edgesStr.substring(objStart, objEnd + 1);

            String from = extractString(obj, "from");
            String to = extractString(obj, "to");
            double weight = extractNumber(obj, "weight");

            adj.get(from).add(new String[]{to, String.valueOf(weight)});
            adj.get(to).add(new String[]{from, String.valueOf(weight)});

            pos = objEnd + 1;
        }

        // Dijkstra from "A"
        Map<String, Double> dist = new HashMap<>();
        for (String n : nodes) {
            dist.put(n, Double.POSITIVE_INFINITY);
        }
        dist.put("A", 0.0);

        PriorityQueue<double[]> pq = new PriorityQueue<>(Comparator.comparingDouble(a -> a[0]));
        pq.offer(new double[]{0.0, 0}); // distance, index
        Map<String, Integer> nodeIndex = new HashMap<>();
        for (int idx = 0; idx < nodes.size(); idx++) {
            nodeIndex.put(nodes.get(idx), idx);
        }
        boolean[] visited = new boolean[nodes.size()];

        while (!pq.isEmpty()) {
            double[] curr = pq.poll();
            double d = curr[0];
            int uIdx = (int) curr[1];
            if (visited[uIdx]) continue;
            visited[uIdx] = true;
            String u = nodes.get(uIdx);

            for (String[] edge : adj.get(u)) {
                String v = edge[0];
                double w = Double.parseDouble(edge[1]);
                int vIdx = nodeIndex.get(v);
                if (!visited[vIdx] && d + w < dist.get(v)) {
                    dist.put(v, d + w);
                    pq.offer(new double[]{d + w, vIdx});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sortedNodes = new ArrayList<>(nodes);
        Collections.sort(sortedNodes);
        for (String n : sortedNodes) {
            double d = dist.get(n);
            if (d == 0.0) {
                System.out.println("A -> " + n + ": 0");
            } else if (d == Math.floor(d) && !Double.isInfinite(d)) {
                System.out.println("A -> " + n + ": " + (long) d);
            } else if (Double.isInfinite(d)) {
                System.out.println("A -> " + n + ": unreachable");
            } else {
                System.out.println("A -> " + n + ": " + d);
            }
        }
    }

    static int findMatchingBracket(String s, int openIdx) {
        int depth = 0;
        for (int i = openIdx; i < s.length(); i++) {
            if (s.charAt(i) == '[') depth++;
            else if (s.charAt(i) == ']') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static int findMatchingBrace(String s, int openIdx) {
        int depth = 0;
        for (int i = openIdx; i < s.length(); i++) {
            if (s.charAt(i) == '{') depth++;
            else if (s.charAt(i) == '}') {
                depth--;
                if (depth == 0) return i;
            }
        }
        return s.length() - 1;
    }

    static String extractString(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return "";
        int colonIdx = obj.indexOf(':', idx + search.length());
        int q1 = obj.indexOf('"', colonIdx + 1);
        int q2 = obj.indexOf('"', q1 + 1);
        return obj.substring(q1 + 1, q2);
    }

    static double extractNumber(String obj, String key) {
        String search = "\"" + key + "\"";
        int idx = obj.indexOf(search);
        if (idx == -1) return 0;
        int colonIdx = obj.indexOf(':', idx + search.length());
        int start = colonIdx + 1;
        while (start < obj.length() && (obj.charAt(start) == ' ' || obj.charAt(start) == '\t')) start++;
        int end = start;
        while (end < obj.length() && (Character.isDigit(obj.charAt(end)) || obj.charAt(end) == '.' || obj.charAt(end) == '-' || obj.charAt(end) == '+')) {
            end++;
        }
        return Double.parseDouble(obj.substring(start, end));
    }
}

