use std::collections::{BTreeMap, BTreeSet};
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_component_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut error_messages: BTreeSet<String> = BTreeSet::new();
    let mut hour_counts: BTreeMap<u32, usize> = BTreeMap::new();

    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }

        let bracket_end = line.find(']').expect("No closing bracket");
        let timestamp = &line[1..bracket_end];

        let hour: u32 = timestamp[11..13].parse().expect("Invalid hour");
        *hour_counts.entry(hour).or_insert(0) += 1;

        let rest = &line[bracket_end + 2..];

        let paren_start = rest.find('(').expect("No opening paren");
        let level = rest[..paren_start].trim().to_string();

        let paren_end = rest.find(')').expect("No closing paren");
        let component = rest[paren_start + 1..paren_end].to_string();

        let after_paren = &rest[paren_end + 1..];
        let message = after_paren.strip_prefix(" - ").unwrap_or(after_paren).to_string();

        *level_counts.entry(level.clone()).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component).or_insert(0) += 1;
            error_messages.insert(message);
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_comp, top_count) = error_component_counts.iter().max_by_key(|(_, c)| *c).unwrap();
    println!("Component with Most Errors: {} ({} errors)", top_comp, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (busiest_hour, busiest_count) = hour_counts.iter().max_by_key(|(_, c)| *c).unwrap();
    println!("Busiest Hour: {:02}:00 ({} entries)", busiest_hour, busiest_count);
}

