    char *dept;
    double salary;
} Emp;

static char *dupstr(const char *s)
{
    size_t n = strlen(s) + 1;
    char *p = (char *)malloc(n);
    if (p) memcpy(p, s, n);
    return p;
}

static int cmp_str(const void *a, const void *b)
{
    return strcmp(*(char *const *)a, *(char *const *)b);
}

static void fmt_commas(long long v, char *out)
{
    if (v < 0) { *out++ = '-'; v = -v; }
    char tmp[32];
    int n = 0;
    if (v == 0) tmp[n++] = '0';
    while (v > 0) { tmp[n++] = (char)('0' + (v % 10)); v /= 10; }
    int i = 0;
    for (int j = n - 1; j >= 0; j--) {
        if (i > 0 && i % 3 == 0) *out++ = ',';
        *out++ = tmp[j];
        i++;
    }
    *out = '\0';
}

int main(void)
{
    const char *path = "<tmp>";
    FILE *f = fopen(path, "r");
    if (!f) {
        fprintf(stderr, "error: cannot open %s\n", path);
        return 1;
    }

    size_t cap = 64, n = 0;
    Emp *emps = (Emp *)malloc(cap * sizeof *emps);
    char *line = (char *)malloc(65536);
    if (!emps || !line) return 1;

    int first = 1;
    while (fgets(line, 65536, f)) {
        size_t L = strlen(line);
        while (L > 0 && (line[L - 1] == '\n' || line[L - 1] == '\r')) line[--L] = '\0';
        if (L == 0) continue;
        if (first) {
            first = 0;
            if (strstr(line, "employee_id")) continue;
        }
        char *c1 = strchr(line, ',');
        if (!c1) continue;
        *c1 = '\0';
        char *name = c1 + 1;
        char *c2 = strchr(name, ',');
        if (!c2) continue;
        *c2 = '\0';
        char *dept = c2 + 1;
        char *c3 = strchr(dept, ',');
        if (!c3) continue;
        *c3 = '\0';
        char *salstr = c3 + 1;
        double sal = strtod(salstr, NULL);
        if (n == cap) {
            cap *= 2;
            emps = (Emp *)realloc(emps, cap * sizeof *emps);
            if (!emps) return 1;
        }
        emps[n].name = dupstr(name);
        emps[n].dept = dupstr(dept);
        emps[n].salary = sal;
        n++;
    }
    fclose(f);
    free(line);
    if (n == 0) { free(emps); return 0; }

    char **depts = (char **)malloc(n * sizeof *depts);
    int nd = 0;
    for (size_t i = 0; i < n; i++) {
        int found = 0;
        for (int j = 0; j < nd; j++) {
            if (strcmp(depts[j], emps[i].dept) == 0) { found = 1; break; }
        }
        if (!found) depts[nd++] = emps[i].dept;
    }
    qsort(depts, (size_t)nd, sizeof *depts, cmp_str);

    double *sums = (double *)calloc((size_t)nd, sizeof *sums);
    int *cnts = (int *)calloc((size_t)nd, sizeof *cnts);
    int hi = 0;
    double total = 0.0;
    for (size_t i = 0; i < n; i++) {
        for (int j = 0; j < nd; j++) {
            if (strcmp(depts[j], emps[i].dept) == 0) {
                sums[j] += emps[i].salary;
                cnts[j]++;
                break;
            }
        }
        total += emps[i].salary;
        if (i == 0 || emps[i].salary > emps[hi].salary) hi = (int)i;
    }

    char buf[64];

    printf("=== Salary Report ===\n\n");
    printf("Average Salary by Department:\n");
    for (int j = 0; j < nd; j++) {
        double avg = sums[j] / (double)cnts[j];
        long long cents = llround(avg * 100.0);
        long long ip = cents / 100;
        int frac = (int)(cents % 100);
        if (frac < 0) frac = -frac;
        fmt_commas(ip, buf);
        printf("  %s: $%s.%02d\n", depts[j], buf, frac);
    }

    fmt_commas(llround(emps[hi].salary), buf);
    printf("\nHighest Paid: %s ($%s)\n", emps[hi].name, buf);

    printf("\nDepartments with >2 employees:\n");
    for (int j = 0; j < nd; j++) {
        if (cnts[j] > 2)
            printf("  %s (%d employees)\n", depts[j], cnts[j]);
    }

    fmt_commas(llround(total), buf);
    printf("\nTotal Budget: $%s\n", buf);

    for (size_t i = 0; i < n; i++) { free(emps[i].name); free(emps[i].dept); }
    free(emps);
    free(depts);
    free(sums);
    free(cnts);
    return 0;
}

