import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(buffer: Buffer): number {
  if (buffer.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < buffer.length; i++) {
    if (buffer[i] === 0x0a) count++;
  }
  if (buffer[buffer.length - 1] !== 0x0a) count++;
  return count;
}

function walkDir(dir: string, root: string, visited: Set<string>, result: Map<string, FileInfo[]>): void {
  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch (e) {
    return;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch (e) {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      walkDir(fullPath, root, visited, result);
    } else if (entry.isFile()) {
      const relativePath = path.relative(root, fullPath).split(path.sep).join('/');
      let buffer: Buffer;
      try {
        buffer = fs.readFileSync(fullPath);
      } catch (e) {
        continue;
      }
      const lines = countLines(buffer);
      const chars = buffer.length;
      const ext = path.extname(entry.name);
      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }
}

const visited = new Set<string>();
try {
  const rootReal = fs.realpathSync(rootDir);
  visited.add(rootReal);
} catch (e) {
  process.exit(1);
}

const fileMap = new Map<string, FileInfo[]>();
walkDir(rootDir, rootDir, visited, fileMap);

const exts = Array.from(fileMap.keys()).sort();

for (const ext of exts) {
  fileMap.get(ext)!.sort((a, b) => a.relativePath.localeCompare(b.relativePath));
}

let output = '';
output += '=== File Tree Analysis ===\n';
output += '\n';

let totalFiles = 0;
let totalLines = 0;
let totalChars = 0;

for (const ext of exts) {
  const files = fileMap.get(ext)!;
  const extLines = files.reduce((s, f) => s + f.lines, 0);
  const extChars = files.reduce((s, f) => s + f.chars, 0);

  output += `Extension: ${ext}\n`;
  output += `  Files: ${files.length}\n`;
  output += `  Total Lines: ${extLines}\n`;
  output += `  Total Characters: ${extChars}\n`;

  for (const f of files) {
    output += `    ${f.relativePath}: ${f.lines} lines, ${f.chars} chars\n`;
  }

  totalFiles += files.length;
  totalLines += extLines;
  totalChars += extChars;
}

output += '\n';
output += `Total: ${totalFiles} files, ${totalLines} lines, ${totalChars} characters\n`;

process.stdout.write(output);

