                if (nd < nodes[e->to].dist) {
                    nodes[e->to].dist = nd;
                }
            }
            e = e->next;
        }
    }

    /* Sort node indices alphabetically by name */
    int *order = malloc((size_t)num_nodes * sizeof(int));
    for (int i = 0; i < num_nodes; i++) order[i] = i;

    /* Simple insertion sort using strcmp */
    for (int i = 1; i < num_nodes; i++) {
        int key = order[i];
        int j = i - 1;
        while (j >= 0 && strcmp(node_names[order[j]], node_names[key]) > 0) {
            order[j + 1] = order[j];
            j--;
        }
        order[j + 1] = key;
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        printf("A -> %s: %lld\n", node_names[idx], nodes[idx].dist);
    }

    free(json);
    return 0;
}
