struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var files: [String: [FileInfo]] = [:]
var visitedDirs: Set<String> = []

func walk(dir: String) {
    let dirURL = URL(fileURLWithPath: dir)
    let resolvedPath = dirURL.resolvingSymlinksInPath().standardizedFileURL.path
    if visitedDirs.contains(resolvedPath) { return }
    visitedDirs.insert(resolvedPath)

    guard let contents = try? FileManager.default.contentsOfDirectory(
        at: dirURL,
        includingPropertiesForKeys: [.isRegularFileKey, .isSymbolicLinkKey, .isDirectoryKey],
        options: []
    ) else { return }

    for url in contents {
        let values = (try? url.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey])) ?? .init()
        if values.isSymbolicLink == true { continue }

        if values.isDirectory == true {
            walk(dir: url.path)
        } else {
            let relativePath = String(url.path.dropFirst(baseDir.count + 1))
            guard let data = try? Data(contentsOf: url) else { continue }
            let chars = data.count
            let content = String(data: data, encoding: .utf8) ?? ""

            let lineCount: Int
            if content.isEmpty {
                lineCount = 0
            } else {
                let parts = content.components(separatedBy: "\n")
                if content.hasSuffix("\n") {
                    lineCount = parts.count - 1
                } else {
                    lineCount = parts.count
                }
            }

            let ext = url.pathExtension
            let extKey = ext.isEmpty ? "" : "." + ext

            files[extKey, default: []].append(FileInfo(relativePath: relativePath, lines: lineCount, chars: chars))
        }
    }
}

