use std::fs;
use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

#[derive(Debug, Clone)]
enum Json {
    Object(Vec<(String, Json)>),
    Array(Vec<Json>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.chars.len() && self.chars[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next_char(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        assert_eq!(self.next_char(), Some(c));
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => { self.pos += 4; Json::Bool(true) }
            Some('f') => { self.pos += 5; Json::Bool(false) }
            Some('n') => { self.pos += 4; Json::Null }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Json {
        self.expect('{');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.next_char();
            return Json::Object(items);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.expect(':');
            let val = self.parse();
            items.push((key, val));
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected , or } in object"),
            }
        }
        Json::Object(items)
    }

    fn parse_array(&mut self) -> Json {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next_char();
            return Json::Array(items);
        }
        loop {
            let val = self.parse();
            items.push(val);
            self.skip_whitespace();
            match self.next_char() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected , or ] in array"),
            }
        }
        Json::Array(items)
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            match self.next_char() {
                Some('"') => break,
                Some('\\') => {
                    match self.next_char() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('u') => {
                            let mut code: u32 = 0;
                            for _ in 0..4 {
                                let c = self.next_char().unwrap();
                                code = code * 16 + c.to_digit(16).unwrap();
                            }
                            s.push(char::from_u32(code).unwrap());
                        }
                        _ => panic!("Bad escape sequence"),
                    }
                }
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        self.skip_whitespace();
        let start = self.pos;
        while self.pos < self.chars.len() {
            let c = self.chars[self.pos];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        Json::Number(s.parse().unwrap())
    }
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read graph.json");
    let mut parser = Parser::new(&content);
    let json = parser.parse();

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<(String, String, f64)> = Vec::new();

    if let Json::Object(ref fields) = json {
        for (key, val) in fields {
            if key == "nodes" {
                if let Json::Array(ref arr) = val {
                    for item in arr {
                        if let Json::String(s) = item {
                            nodes.push(s.clone());
                        }
                    }
                }
            } else if key == "edges" {
                if let Json::Array(ref arr) = val {
                    for item in arr {
                        if let Json::Object(ref efields) = item {
                            let mut from = String::new();
                            let mut to = String::new();
                            let mut weight = 0.0f64;
                            for (k, v) in efields {
                                if k == "from" {
