                                } else if k == "weight" {
                                    if let Json::Number(n) = v { weight = *n; }
                                }
                            }
                            edges.push((from, to, weight));
                        }
                    }
                }
            }
        }
    }

    // Build undirected adjacency list
    let mut adj: HashMap<String, Vec<(String, f64)>> = HashMap::new();
    for node in &nodes {
        adj.entry(node.clone()).or_insert_with(Vec::new);
    }
    for (from, to, weight) in &edges {
        adj.entry(from.clone()).or_insert_with(Vec::new).push((to.clone(), *weight));
        adj.entry(to.clone()).or_insert_with(Vec::new).push((from.clone(), *weight));
    }

    // Dijkstra's algorithm from "A"
    let source = "A".to_string();
    let mut dist: HashMap<String, f64> = HashMap::new();
    for node in &nodes {
        dist.insert(node.clone(), f64::INFINITY);
    }
    dist.insert(source.clone(), 0.0);

    let mut heap: BinaryHeap<Reverse<(F64Ord, String)>> = BinaryHeap::new();
    heap.push(Reverse((F64Ord(0.0), source.clone())));

    while let Some(Reverse((fd, u))) = heap.pop() {
        let d = fd.0;
        if d > *dist.get(&u).unwrap() {
            continue;
        }
        if let Some(neighbors) = adj.get(&u) {
            for (v, w) in neighbors {
                let new_dist = d + w;
                if new_dist < *dist.get(v).unwrap() {
                    dist.insert(v.clone(), new_dist);
                    heap.push(Reverse((F64Ord(new_dist), v.clone())));
                }
            }
        }
    }

    // Output
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted_nodes: Vec<&String> = nodes.iter().collect();
    sorted_nodes.sort();

    for node in sorted_nodes {
        let d = dist.get(node).unwrap();
        if *d == f64::INFINITY {
            println!("A -> {}: unreachable", node);
        } else if d.fract() == 0.0 {
            println!("A -> {}: {}", node, *d as i64);
        } else {
            println!("A -> {}: {}", node, d);
        }
    }
}
