#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <ctype.h>

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} JsonType;

typedef struct JsonValue JsonValue;

struct JsonValue {
    JsonType type;
    int boolean;
    double number;
    char *string;
    JsonValue **array_items;
    int array_count;
    int array_cap;
    char **obj_keys;
    JsonValue **obj_values;
    int obj_count;
    int obj_cap;
};

static JsonValue *json_new(void) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    return v;
}

static void json_free(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_STRING) free(v->string);
    if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->array_count; i++) json_free(v->array_items[i]);
        free(v->array_items);
    }
    if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->obj_count; i++) {
            free(v->obj_keys[i]);
            json_free(v->obj_values[i]);
        }
        free(v->obj_keys);
        free(v->obj_values);
    }
    free(v);
}

/* Parser */
typedef struct {
    const char *s;
    int pos;
    int len;
} Parser;

static void skip_ws(Parser *p) {
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static JsonValue *parse_value(Parser *p);

static char *parse_string_raw(Parser *p) {
    /* assumes p->s[p->pos] == '"' */
    p->pos++; /* skip opening quote */
    int cap = 64;
    int count = 0;
    char *buf = (char *)malloc(cap);
    while (p->pos < p->len && p->s[p->pos] != '"') {
        char c = p->s[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char e = p->s[p->pos];
            switch (e) {
                case '"': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '"'; break;
                case '\\': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\\'; break;
                case '/': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '/'; break;
                case 'b': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\b'; break;
                case 'f': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\f'; break;
                case 'n': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\n'; break;
                case 'r': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\r'; break;
                case 't': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\t'; break;
                case 'u': {
                    /* parse 4 hex digits */
                    if (p->pos + 4 >= p->len) { p->pos++; break; }
                    unsigned int code = 0;
                    for (int i = 1; i <= 4; i++) {
                        char h = p->s[p->pos + i];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (h - 'A' + 10);
                    }
                    p->pos += 4;
                    /* encode as UTF-8 (basic BMP only) */
                    if (code < 0x80) {
                        if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[count++] = (char)code;
                    } else if (code < 0x800) {
                        if (count + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[count++] = (char)(0xC0 | (code >> 6));
                        buf[count++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        if (count + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[count++] = (char)(0xE0 | (code >> 12));
                        buf[count++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        buf[count++] = (char)(0x80 | (code & 0x3F));
                    }
                    break;
                }
                default: if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = e; break;
            }
        } else {
            if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[count++] = c;
        }
        p->pos++;
    }
    if (p->pos < p->len) p->pos++; /* skip closing quote */
    if (count + 1 >= cap) { cap = count + 1; buf = realloc(buf, cap); }
    buf[count] = '\0';
    return buf;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new(); /* NULL */
    char c = p->s[p->pos];
    JsonValue *v = json_new();
    if (c == '{') {
        v->type = JSON_OBJECT;
        p->pos++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; return v; }
        while (p->pos < p->len) {
            skip_ws(p);
            if (p->pos >= p->len) break;
            if (p->s[p->pos] != '"') break;
            char *key = parse_string_raw(p);
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ':') p->pos++;
            JsonValue *val = parse_value(p);
            if (v->obj_count >= v->obj_cap) {
                v->obj_cap = v->obj_cap ? v->obj_cap * 2 : 8;
                v->obj_keys = realloc(v->obj_keys, v->obj_cap * sizeof(char *));
                v->obj_values = realloc(v->obj_values, v->obj_cap * sizeof(JsonValue *));
            }
            v->obj_keys[v->obj_count] = key;
            v->obj_values[v->obj_count] = val;
            v->obj_count++;
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
            if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; break; }
            break;
        }
        return v;
    } else if (c == '[') {
        v->type = JSON_ARRAY;
        p->pos++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return v; }
        while (p->pos < p->len) {
            JsonValue *item = parse_value(p);
            if (v->array_count >= v->array_cap) {
                v->array_cap = v->array_cap ? v->array_cap * 2 : 8;
                v->array_items = realloc(v->array_items, v->array_cap * sizeof(JsonValue *));
            }
            v->array_items[v->array_count++] = item;
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
            if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; break; }
            break;
        }
        return v;
    } else if (c == '"') {
        v->type = JSON_STRING;
        v->string = parse_string_raw(p);
        return v;
    } else if (c == 't') {
        v->type = JSON_BOOL; v->boolean = 1; p->pos += 4; return v;
    } else if (c == 'f') {
        v->type = JSON_BOOL; v->boolean = 0; p->pos += 5; return v;
    } else if (c == 'n') {
        v->type = JSON_NULL; p->pos += 4; return v;
    } else {
        /* number */
        char *end;
        v->type = JSON_NUMBER;
        v->number = strtod(p->s + p->pos, &end);
        p->pos += (int)(end - (p->s + p->pos));
        return v;
    }
}

/* Deep equality */
static int json_equal(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->array_count != b->array_count) return 0;
            for (int i = 0; i < a->array_count; i++)
                if (!json_equal(a->array_items[i], b->array_items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->obj_count != b->obj_count) return 0;
            for (int i = 0; i < a->obj_count; i++) {
                int found = 0;
                for (int j = 0; j < b->obj_count; j++) {
                    if (strcmp(a->obj_keys[i], b->obj_keys[j]) == 0) {
                        if (!json_equal(a->obj_values[i], b->obj_values[j])) return 0;
                        found = 1; break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

/* Check if item is in array (for dedup) */
static int array_contains(JsonValue **items, int count, JsonValue *target) {
    for (int i = 0; i < count; i++) {
        if (json_equal(items[i], target)) return 1;
    }
    return 0;
}

/* Deep copy */
static JsonValue *json_clone(JsonValue *v) {
    JsonValue *c = json_new();
    c->type = v->type;
    switch (v->type) {
        case JSON_NULL: break;
        case JSON_BOOL: c->boolean = v->boolean; break;
        case JSON_NUMBER: c->number = v->number; break;
        case JSON_STRING: c->string = strdup(v->string); break;
        case JSON_ARRAY:
            c->array_count = v->array_count;
            c->array_cap = v->array_count;
            c->array_items = (JsonValue **)malloc(c->array_cap * sizeof(JsonValue *));
            for (int i = 0; i < v->array_count; i++)
                c->array_items[i] = json_clone(v->array_items[i]);
