    JsonValue **obj_values;
    int obj_count;
    int obj_cap;
};

static JsonValue *json_new(void) {
    JsonValue *v = (JsonValue *)calloc(1, sizeof(JsonValue));
    return v;
}

static void json_free(JsonValue *v) {
    if (!v) return;
    if (v->type == JSON_STRING) free(v->string);
    if (v->type == JSON_ARRAY) {
        for (int i = 0; i < v->array_count; i++) json_free(v->array_items[i]);
        free(v->array_items);
    }
    if (v->type == JSON_OBJECT) {
        for (int i = 0; i < v->obj_count; i++) {
            free(v->obj_keys[i]);
            json_free(v->obj_values[i]);
        }
        free(v->obj_keys);
        free(v->obj_values);
    }
    free(v);
}

/* Parser */
typedef struct {
    const char *s;
    int pos;
    int len;
} Parser;

static void skip_ws(Parser *p) {
    while (p->pos < p->len) {
        char c = p->s[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static JsonValue *parse_value(Parser *p);

static char *parse_string_raw(Parser *p) {
    p->pos++;
    int cap = 64;
    int count = 0;
    char *buf = (char *)malloc(cap);
    while (p->pos < p->len && p->s[p->pos] != '"') {
        char c = p->s[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char e = p->s[p->pos];
            switch (e) {
                case '"': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '"'; break;
                case '\\': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\\'; break;
                case '/': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '/'; break;
                case 'b': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\b'; break;
                case 'f': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\f'; break;
                case 'n': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\n'; break;
                case 'r': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\r'; break;
                case 't': if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = '\t'; break;
                case 'u': {
                    if (p->pos + 4 >= p->len) { p->pos++; break; }
                    unsigned int code = 0;
                    for (int i = 1; i <= 4; i++) {
                        char h = p->s[p->pos + i];
                        code <<= 4;
                        if (h >= '0' && h <= '9') code |= (h - '0');
                        else if (h >= 'a' && h <= 'f') code |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') code |= (h - 'A' + 10);
                    }
                    p->pos += 4;
                    if (code < 0x80) {
                        if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[count++] = (char)code;
                    } else if (code < 0x800) {
                        if (count + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[count++] = (char)(0xC0 | (code >> 6));
                        buf[count++] = (char)(0x80 | (code & 0x3F));
                    } else {
                        if (count + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[count++] = (char)(0xE0 | (code >> 12));
                        buf[count++] = (char)(0x80 | ((code >> 6) & 0x3F));
                        buf[count++] = (char)(0x80 | (code & 0x3F));
                    }
                    break;
                }
                default: if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); } buf[count++] = e; break;
            }
        } else {
            if (count + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[count++] = c;
        }
        p->pos++;
    }
    if (p->pos < p->len) p->pos++;
    if (count + 1 >= cap) { cap = count + 1; buf = realloc(buf, cap); }
    buf[count] = '\0';
    return buf;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) return json_new();
    char c = p->s[p->pos];
    JsonValue *v = json_new();
    if (c == '{') {
        v->type = JSON_OBJECT;
        p->pos++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; return v; }
        while (p->pos < p->len) {
            skip_ws(p);
            if (p->pos >= p->len) break;
            if (p->s[p->pos] != '"') break;
            char *key = parse_string_raw(p);
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ':') p->pos++;
            JsonValue *val = parse_value(p);
            if (v->obj_count >= v->obj_cap) {
                v->obj_cap = v->obj_cap ? v->obj_cap * 2 : 8;
                v->obj_keys = realloc(v->obj_keys, v->obj_cap * sizeof(char *));
                v->obj_values = realloc(v->obj_values, v->obj_cap * sizeof(JsonValue *));
            }
            v->obj_keys[v->obj_count] = key;
            v->obj_values[v->obj_count] = val;
            v->obj_count++;
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
            if (p->pos < p->len && p->s[p->pos] == '}') { p->pos++; break; }
            break;
        }
        return v;
    } else if (c == '[') {
        v->type = JSON_ARRAY;
        p->pos++;
        skip_ws(p);
        if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; return v; }
        while (p->pos < p->len) {
            JsonValue *item = parse_value(p);
            if (v->array_count >= v->array_cap) {
                v->array_cap = v->array_cap ? v->array_cap * 2 : 8;
                v->array_items = realloc(v->array_items, v->array_cap * sizeof(JsonValue *));
            }
            v->array_items[v->array_count++] = item;
            skip_ws(p);
            if (p->pos < p->len && p->s[p->pos] == ',') { p->pos++; continue; }
            if (p->pos < p->len && p->s[p->pos] == ']') { p->pos++; break; }
            break;
        }
        return v;
    } else if (c == '"') {
        v->type = JSON_STRING;
        v->string = parse_string_raw(p);
        return v;
    } else if (c == 't') {
        v->type = JSON_BOOL; v->boolean = 1; p->pos += 4; return v;
    } else if (c == 'f') {
        v->type = JSON_BOOL; v->boolean = 0; p->pos += 5; return v;
    } else if (c == 'n') {
        v->type = JSON_NULL; p->pos += 4; return v;
    } else {
        char *end;
        v->type = JSON_NUMBER;
        v->number = strtod(p->s + p->pos, &end);
        p->pos += (int)(end - (p->s + p->pos));
        return v;
    }
}

static int json_equal(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->boolean == b->boolean;
        case JSON_NUMBER: return a->number == b->number;
        case JSON_STRING: return strcmp(a->string, b->string) == 0;
        case JSON_ARRAY:
            if (a->array_count != b->array_count) return 0;
            for (int i = 0; i < a->array_count; i++)
                if (!json_equal(a->array_items[i], b->array_items[i])) return 0;
            return 1;
        case JSON_OBJECT:
            if (a->obj_count != b->obj_count) return 0;
            for (int i = 0; i < a->obj_count; i++) {
                int found = 0;
                for (int j = 0; j < b->obj_count; j++) {
                    if (strcmp(a->obj_keys[i], b->obj_keys[j]) == 0) {
                        if (!json_equal(a->obj_values[i], b->obj_values[j])) return 0;
                        found = 1; break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
    }
    return 0;
}

static int array_contains(JsonValue **items, int count, JsonValue *target) {
    for (int i = 0; i < count; i++) {
        if (json_equal(items[i], target)) return 1;
    }
    return 0;
}

static JsonValue *json_clone(JsonValue *v) {
    JsonValue *c = json_new();
    c->type = v->type;
    switch (v->type) {
        case JSON_NULL: break;
        case JSON_BOOL: c->boolean = v->boolean; break;
        case JSON_NUMBER: c->number = v->number; break;
        case JSON_STRING: c->string = strdup(v->string); break;
        case JSON_ARRAY:
            c->array_count = v->array_count;
            c->array_cap = v->array_count;
            if (c->array_count > 0)
                c->array_items = (JsonValue **)malloc(c->array_cap * sizeof(JsonValue *));
            for (int i = 0; i < v->array_count; i++)
                c->array_items[i] = json_clone(v->array_items[i]);
            break;
        case JSON_OBJECT:
            c->obj_count = v->obj_count;
            c->obj_cap = v->obj_count;
            if (c->obj_count > 0) {
                c->obj_keys = (char **)malloc(c->obj_cap * sizeof(char *));
                c->obj_values = (JsonValue **)malloc(c->obj_cap * sizeof(JsonValue *));
            }
            for (int i = 0; i < v->obj_count; i++) {
                c->obj_keys[i] = strdup(v->obj_keys[i]);
                c->obj_values[i] = json_clone(v->obj_values[i]);
            }
            break;
    }
    return c;
}

static JsonValue *json_merge(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new();
        result->type = JSON_OBJECT;
        result->obj_cap = a->obj_count + b->obj_count + 4;
        result->obj_keys = (char **)malloc(result->obj_cap * sizeof(char *));
        result->obj_values = (JsonValue **)malloc(result->obj_cap * sizeof(JsonValue *));
        result->obj_count = 0;

        for (int i = 0; i < a->obj_count; i++) {
            int found_in_b = 0;
            for (int j = 0; j < b->obj_count; j++) {
                if (strcmp(a->obj_keys[i], b->obj_keys[j]) == 0) {
                    JsonValue *merged = json_merge(a->obj_values[i], b->obj_values[j]);
                    if (result->obj_count >= result->obj_cap) {
                        result->obj_cap *= 2;
                        result->obj_keys = realloc(result->obj_keys, result->obj_cap * sizeof(char *));
                        result->obj_values = realloc(result->obj_values, result->obj_cap * sizeof(JsonValue *));
                    }
                    result->obj_keys[result->obj_count] = strdup(a->obj_keys[i]);
                    result->obj_values[result->obj_count] = merged;
                    result->obj_count++;
                    found_in_b = 1;
                    break;
                }
            }
            if (!found_in_b) {
                if (result->obj_count >= result->obj_cap) {
                    result->obj_cap *= 2;
                    result->obj_keys = realloc(result->obj_keys, result->obj_cap * sizeof(char *));
                    result->obj_values = realloc(result->obj_values, result->obj_cap * sizeof(JsonValue *));
                }
                result->obj_keys[result->obj_count] = strdup(a->obj_keys[i]);
                result->obj_values[result->obj_count] = json_clone(a->obj_values[i]);
                result->obj_count++;
            }
        }

        for (int j = 0; j < b->obj_count; j++) {
            int found_in_a = 0;
            for (int i = 0; i < a->obj_count; i++) {
                if (strcmp(b->obj_keys[j], a->obj_keys[i]) == 0) { found_in_a = 1; break; }
            }
            if (!found_in_a) {
                if (result->obj_count >= result->obj_cap) {
                    result->obj_cap *= 2;
                    result->obj_keys = realloc(result->obj_keys, result->obj_cap * sizeof(char *));
                    result->obj_values = realloc(result->obj_values, result->obj_cap * sizeof(JsonValue *));
                }
                result->obj_keys[result->obj_count] = strdup(b->obj_keys[j]);
                result->obj_values[result->obj_count] = json_clone(b->obj_values[j]);
                result->obj_count++;
            }
        }
        return result;
    } else if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new();
        result->type = JSON_ARRAY;
        result->array_cap = a->array_count + b->array_count + 4;
        result->array_items = (JsonValue **)malloc(result->array_cap * sizeof(JsonValue *));
        result->array_count = 0;

        for (int i = 0; i < a->array_count; i++) {
            if (result->array_count >= result->array_cap) {
                result->array_cap *= 2;
                result->array_items = realloc(result->array_items, result->array_cap * sizeof(JsonValue *));
            }
            result->array_items[result->array_count++] = json_clone(a->array_items[i]);
        }

        for (int j = 0; j < b->array_count; j++) {
            if (!array_contains(result->array_items, result->array_count, b->array_items[j])) {
                if (result->array_count >= result->array_cap) {
                    result->array_cap *= 2;
                    result->array_items = realloc(result->array_items, result->array_cap * sizeof(JsonValue *));
                }
                result->array_items[result->array_count++] = json_clone(b->array_items[j]);
            }
        }
        return result;
    } else {
        return json_clone(b);
    }
}

static void print_escaped_string(const char *s) {
    putchar('"');
    for (const char *p = s; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if (c < 0x20) printf("\\u%04x", c);
                else putchar(c);
                break;
        }
    }
    putchar('"');
}

static void print_number(double d) {
    if (isnan(d) || isinf(d)) {
        fputs("null", stdout);
        return;
    }
    if (d == (double)(long long)d && fabs(d) < 1e15) {
        printf("%lld", (long long)d);
    } else {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.15g", d);
        fputs(buf, stdout);
    }
}

static void print_json(JsonValue *v, int indent) {
    switch (v->type) {
        case JSON_NULL:
            fputs("null", stdout);
            break;
        case JSON_BOOL:
            fputs(v->boolean ? "true" : "false", stdout);
            break;
        case JSON_NUMBER:
            print_number(v->number);
            break;
        case JSON_STRING:
            print_escaped_string(v->string);
            break;
        case JSON_ARRAY:
            if (v->array_count == 0) {
                fputs("[]", stdout);
                return;
            }
            fputs("[\n", stdout);
            for (int i = 0; i < v->array_count; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) putchar(' ');
                print_json(v->array_items[i], indent + 1);
                if (i < v->array_count - 1) putchar(',');
                putchar('\n');
            }
            for (int s = 0; s < indent * 2; s++) putchar(' ');
            fputs("]", stdout);
            break;
        case JSON_OBJECT: {
            if (v->obj_count == 0) {
                fputs("{}", stdout);
                return;
            }
            int n = v->obj_count;
            int *idx = (int *)malloc(n * sizeof(int));
            for (int i = 0; i < n; i++) idx[i] = i;
            for (int i = 1; i < n; i++) {
                int key = idx[i];
                int j = i - 1;
                while (j >= 0 && strcmp(v->obj_keys[idx[j]], v->obj_keys[key]) > 0) {
                    idx[j + 1] = idx[j];
                    j--;
                }
                idx[j + 1] = key;
            }
            fputs("{\n", stdout);
            for (int i = 0; i < n; i++) {
                for (int s = 0; s < (indent + 1) * 2; s++) putchar(' ');
                print_escaped_string(v->obj_keys[idx[i]]);
                fputs(": ", stdout);
                print_json(v->obj_values[idx[i]], indent + 1);
                if (i < n - 1) putchar(',');
                putchar('\n');
            }
            for (int s = 0; s < indent * 2; s++) putchar(' ');
            fputs("}", stdout);
            free(idx);
            break;
        }
    }
}

static char *read_file(const char *path, long *out_len) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(len + 1);
    if (fread(buf, 1, len, f) != (size_t)len) {
        fprintf(stderr, "Error: cannot read %s\n", path);
        exit(1);
    }
    buf[len] = '\0';
    fclose(f);
    *out_len = len;
    return buf;
}

int main(void) {
    long len_a, len_b;
    char *file_a = read_file("<tmp>", &len_a);
    char *file_b = read_file("<tmp>", &len_b);

    Parser pa = { file_a, 0, (int)len_a };
    Parser pb = { file_b, 0, (int)len_b };

    JsonValue *a = parse_value(&pa);
    JsonValue *b = parse_value(&pb);

    JsonValue *merged = json_merge(a, b);

    print_json(merged, 0);
    putchar('\n');

    json_free(a);
    json_free(b);
    json_free(merged);
    free(file_a);
    free(file_b);
    return 0;
}
