#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <sys/types.h>

typedef struct {
    char *relpath;
    long lines;
    long chars;
} FileInfo;

typedef struct {
    char *ext;
    FileInfo *files;
    int count;
    int capacity;
} ExtGroup;

static FileInfo *all_files = NULL;
static int all_files_count = 0;
static int all_files_cap = 0;

static ExtGroup *groups = NULL;
static int groups_count = 0;
static int groups_cap = 0;

static void add_file(const char *relpath, long lines, long chars) {
    if (all_files_count >= all_files_cap) {
        all_files_cap = all_files_cap * 2 + 64;
        all_files = (FileInfo *)realloc(all_files, all_files_cap * sizeof(FileInfo));
        if (!all_files) { fprintf(stderr, "OOM\n"); exit(1); }
    }
    all_files[all_files_count].relpath = strdup(relpath);
    all_files[all_files_count].lines = lines;
    all_files[all_files_count].chars = chars;
    all_files_count++;
}

static void walk(const char *dir_full, const char *dir_rel) {
    DIR *dir = opendir(dir_full);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char child_full[8192];
        char child_rel[8192];

        if (dir_rel[0] == '\0') {
            snprintf(child_full, sizeof(child_full), "%s/%s", dir_full, entry->d_name);
            snprintf(child_rel, sizeof(child_rel), "%s", entry->d_name);
        } else {
            snprintf(child_full, sizeof(child_full), "%s/%s/%s", dir_full, dir_rel, entry->d_name);
            snprintf(child_rel, sizeof(child_rel), "%s/%s", dir_rel, entry->d_name);
        }

        struct stat st;
        if (lstat(child_full, &st) != 0) continue;
        if (S_ISLNK(st.st_mode)) continue;

        if (S_ISDIR(st.st_mode)) {
            walk(child_full, child_rel);
        } else if (S_ISREG(st.st_mode)) {
            FILE *f = fopen(child_full, "rb");
            if (!f) continue;

            long char_count = 0;
            long line_count = 0;
            int last_char = 0;
            int c;
            while ((c = fgetc(f)) != EOF) {
                char_count++;
                if (c == '\n') line_count++;
                last_char = c;
            }
            fclose(f);

            if (char_count > 0 && last_char != '\n')
                line_count++;

            add_file(child_rel, line_count, char_count);
        }
    }
    closedir(dir);
}

static int cmp_groups(const void *a, const void *b) {
    const ExtGroup *ga = (const ExtGroup *)a;
    const ExtGroup *gb = (const ExtGroup *)b;
    return strcmp(ga->ext, gb->ext);
}

static int cmp_files(const void *a, const void *b) {
    const FileInfo *fa = (const FileInfo *)a;
    const FileInfo *fb = (const FileInfo *)b;
    return strcmp(fa->relpath, fb->relpath);
}

int main(void) {
    const char *base = "<tmp>";

    walk(base, "");

    for (int i = 0; i < all_files_count; i++) {
        const char *fname = all_files[i].relpath;
        const char *last_slash = strrchr(fname, '/');
        const char *basename = last_slash ? last_slash + 1 : fname;

        const char *dot = strrchr(basename, '.');
        const char *ext = "";
        if (dot && dot != basename)
            ext = dot;

        int found = -1;
        for (int g = 0; g < groups_count; g++) {
            if (strcmp(groups[g].ext, ext) == 0) {
                found = g;
                break;
            }
        }
        if (found == -1) {
            if (groups_count >= groups_cap) {
                groups_cap = groups_cap * 2 + 16;
                groups = (ExtGroup *)realloc(groups, groups_cap * sizeof(ExtGroup));
                if (!groups) { fprintf(stderr, "OOM\n"); exit(1); }
            }
            groups[groups_count].ext = strdup(ext);
            groups[groups_count].files = NULL;
            groups[groups_count].count = 0;
            groups[groups_count].capacity = 0;
            found = groups_count++;
        }

        ExtGroup *g = &groups[found];
        if (g->count >= g->capacity) {
            g->capacity = g->capacity * 2 + 16;
            g->files = (FileInfo *)realloc(g->files, g->capacity * sizeof(FileInfo));
            if (!g->files) { fprintf(stderr, "OOM\n"); exit(1); }
        }
        g->files[g->count].relpath = all_files[i].relpath;
        g->files[g->count].lines = all_files[i].lines;
        g->files[g->count].chars = all_files[i].chars;
        g->count++;
    }

    if (groups_count > 1)
        qsort(groups, groups_count, sizeof(ExtGroup), cmp_groups);

    for (int g = 0; g < groups_count; g++) {
        if (groups[g].count > 1)
            qsort(groups[g].files, groups[g].count, sizeof(FileInfo), cmp_files);
    }

    printf("=== File Tree Analysis ===\n");
    printf("\n");

    long total_files = 0, total_lines = 0, total_chars = 0;

    for (int g = 0; g < groups_count; g++) {
        long glines = 0, gchars = 0;
        for (int i = 0; i < groups[g].count; i++) {
            glines += groups[g].files[i].lines;
            gchars += groups[g].files[i].chars;
        }

        printf("Extension: %s\n", groups[g].ext);
        printf("  Files: %d\n", groups[g].count);
        printf("  Total Lines: %ld\n", glines);
        printf("  Total Characters: %ld\n", gchars);

        for (int i = 0; i < groups[g].count; i++) {
            printf("    %s: %ld lines, %ld chars\n",
                   groups[g].files[i].relpath,
                   groups[g].files[i].lines,
                   groups[g].files[i].chars);
        }

        total_files += groups[g].count;
        total_lines += glines;
        total_chars += gchars;
    }

    printf("\n");
    printf("Total: %ld files, %ld lines, %ld characters\n", total_files, total_lines, total_chars);

    return 0;
}

