                        b'/' => bytes.push(b'/'),
                        b'n' => bytes.push(b'\n'),
                        b't' => bytes.push(b'\t'),
                        b'r' => bytes.push(b'\r'),
                        b'b' => bytes.push(0x08),
                        b'f' => bytes.push(0x0C),
                        b'u' => {
                            if self.pos + 4 < self.input.len() {
                                let hex =
                                    std::str::from_utf8(&self.input[self.pos + 1..self.pos + 5])
                                        .unwrap_or("0000");
                                let code = u32::from_str_radix(hex, 16).unwrap_or(0);
                                let ch = char::from_u32(code).unwrap_or('\u{FFFD}');
                                let mut buf = [0u8; 4];
                                bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                                self.pos += 4;
                            }
                        }
                        _ => bytes.push(esc),
                    }
                }
            } else {
                bytes.push(c);
            }
            self.pos += 1;
        }
        String::from_utf8_lossy(&bytes).to_string()
    }

