fn http_get(url: &str) -> String {
    let without_scheme = url.trim_start_matches("http://");
    let mut parts = without_scheme.splitn(2, '/');
    let host_port = parts.next().unwrap_or("127.0.0.1:80");
    let path = parts.next().unwrap_or("/");

    let (host, port) = if host_port.contains(':') {
        let hp: Vec<&str> = host_port.splitn(2, ':').collect();
        (hp[0].to_string(), hp[1].parse::<u16>().unwrap_or(80))
    } else {
        (host_port.to_string(), 80)
    };

    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).expect("Failed to connect");

    let request = format!(
        "GET {} HTTP/1.1\r\nHost: {}\r\nConnection: close\r\n\r\n",
        path, host_port
    );

    stream
        .write_all(request.as_bytes())
        .expect("Failed to write request");

    let mut response = Vec::new();
    stream.read_to_end(&mut response).expect("Failed to read response");

    let response_str = String::from_utf8_lossy(&response).to_string();

    let body = if let Some(idx) = response_str.find("\r\n\r\n") {
        response_str[idx + 4..].to_string()
    } else if let Some(idx) = response_str.find("\n\n") {
        response_str[idx + 2..].to_string()
    } else {
        response_str
    };

    body
}

fn main() {
    let body = http_get("http://127.0.0.1:18923/api/products");

    let mut parser = JsonParser::new(&body);
    let json = parser.parse();

    let mut products: Vec<(String, f64)> = Vec::new();

    if let JsonValue::Array(arr) = json {
        for item in &arr {
            if let JsonValue::Object(obj) = item {
                let mut name = String::new();
                let mut price = 0.0f64;
                for (key, val) in obj {
                    if key == "name" {
                        if let JsonValue::String(s) = val {
                            name = s.clone();
                        }
                    } else if key == "price" {
                        if let JsonValue::Number(n) = val {
                            price = *n;
                        }
                    }
                }
                products.push((name, price));
            }
        }
    }

    let filtered: Vec<(String, f64)> = products
        .into_iter()
        .filter(|(_, price)| *price > 50.00)
        .collect();

    let mut sorted = filtered;
    sorted.sort_by(|a, b| a.0.cmp(&b.0));

    println!("=== Filtered Products (price > $50.00) ===");
    println!();
    for (name, price) in &sorted {
        println!("{}: ${:.2}", name, price);
    }
    println!();
    println!("Count: {}", sorted.len());
    let total: f64 = sorted.iter().map(|(_, p)| p).sum();
    println!("Total: ${:.2}", total);
}

